js') ?>')"><svg xmlns="http://www.w3.org/2000/svg" width="1em" height="1em" viewBox="0 0 24 24" aria-hidden="true"><path fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="1.75" d="m7 7 10 10M17 7 7 17" /></svg></button></div></td></tr><?php endforeach; else: ?><tr><td colspan="6" class="text-center text-muted-foreground py-8"><?= view('partials/empty_table_state', ['message' => 'Tidak ada pengajuan yang menunggu approval.']) ?></td></tr><?php endif; ?>
